{
  "claims": [
    {
      "claim_text": "The wal-index lives in shared memory.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [1] states that the wal-index is maintained in shared memory.",
      "citations": [
        {
          "index": 1,
          "quote": "a data structure called the \"wal-index\" is maintained in shared memory"
        }
      ]
    },
    {
      "claim_text": "Because the wal-index lives in shared memory, all processes using a WAL database must be on the same host.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [0] says all processes using a database must be on the same host computer because WAL requires processes to share memory, and passage [1] explains that shared memory means readers must exist on the same machine.",
      "citations": [
        {
          "index": 0,
          "quote": "All processes using a database must be on the same host computer; WAL does not work over a network filesystem. This is because WAL requires all processes to share a small amount of memory and processes on separate host machines obviously cannot share memory with each other."
        },
        {
          "index": 1,
          "quote": "the use of shared memory means that all readers must exist on the same machine"
        }
      ]
    },
    {
      "claim_text": "Two processes on different machines sharing a database over NFS cannot use WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "The passages state that WAL does not work over a network filesystem; NFS is such a filesystem.",
      "citations": [
        {
          "index": 0,
          "quote": "WAL does not work over a network filesystem."
        },
        {
          "index": 1,
          "quote": "This is why the write-ahead log implementation will not work on a network filesystem."
        }
      ]
    },
    {
      "claim_text": "Being on the same host is enough to guarantee that WAL will work.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [5] says that if the VFS does not support shared-memory methods, attempts to open or convert a database to WAL mode will fail, so being on the same host is not by itself sufficient.",
      "citations": [
        {
          "index": 5,
          "quote": "If the VFS does not support shared-memory methods, then the attempt to open a database that is already in WAL mode, or the attempt to convert a database into WAL mode, will fail."
        }
      ]
    },
    {
      "claim_text": "Since there is only one WAL file, two writers can never be writing at the same moment.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] states there can only be one writer at a time because there is only one WAL file.",
      "citations": [
        {
          "index": 2,
          "quote": "since there is only one WAL file, there can only be one writer at a time."
        }
      ]
    },
    {
      "claim_text": "Readers can run alongside a writer.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [2] states that writers and readers can run at the same time.",
      "citations": [
        {
          "index": 2,
          "quote": "writers and readers can run at the same time."
        }
      ]
    },
    {
      "claim_text": "The single-writer limit can be lifted with BEGIN CONCURRENT.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages do not mention BEGIN CONCURRENT or any way to lift the single-writer limit.",
      "citations": []
    },
    {
      "claim_text": "A process can use WAL without shared memory only if it sets EXCLUSIVE locking mode before its first WAL access.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [3] states WAL databases can be used even if shared memory is unavailable as long as locking_mode is set to EXCLUSIVE before the first attempted access; passage [4] explains that in this case shared-memory methods are never called.",
      "citations": [
        {
          "index": 3,
          "quote": "WAL databases can be created, read, and written even if shared memory is unavailable as long as the locking_mode is set to EXCLUSIVE before the first attempted access."
        }
      ]
    },
    {
      "claim_text": "In that case, the process stays in EXCLUSIVE mode until it leaves WAL journal mode.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [4] states the connection remains in EXCLUSIVE mode as long as the journal mode is WAL and that the only way out is to change out of WAL journal mode first.",
      "citations": [
        {
          "index": 4,
          "quote": "the database connection remains in EXCLUSIVE mode as long as the journal mode is WAL"
        },
        {
          "index": 4,
          "quote": "The only way to change out of EXCLUSIVE locking mode is to first change out of WAL journal mode."
        }
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, commits skip the WAL sync.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [6] states writers omit the WAL sync on commit when PRAGMA synchronous is set to NORMAL.",
      "citations": [
        {
          "index": 6,
          "quote": "(Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL but omit this sync if PRAGMA synchronous is set to NORMAL.)"
        }
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=NORMAL, the checkpoint is the only operation that issues a sync.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [7] states that with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation.",
      "citations": [
        {
          "index": 7,
          "quote": "with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation (fsync() on unix or FlushFileBuffers() on windows)."
        }
      ]
    },
    {
      "claim_text": "With PRAGMA synchronous=FULL, every commit syncs the WAL.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage [6] states writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL.",
      "citations": [
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL"
        }
      ]
    },
    {
      "claim_text": "Running the checkpoint in a separate thread guarantees that the main thread never blocks on a sync, whatever the synchronous setting.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage [7] gives the no-blocking benefit in the context of PRAGMA synchronous set to NORMAL, but passage [6] states that with FULL, writers sync the WAL on every transaction commit, so the guarantee does not hold whatever the synchronous setting.",
      "citations": [
        {
          "index": 7,
          "quote": "with PRAGMA synchronous set to NORMAL, the checkpoint is the only operation to issue an I/O barrier or sync operation (fsync() on unix or FlushFileBuffers() on windows)."
        },
        {
          "index": 7,
          "quote": "If an application therefore runs checkpoint in a separate thread or process, the main thread or process that is doing database queries and updates will never block on a sync operation."
        },
        {
          "index": 6,
          "quote": "Writers sync the WAL on every transaction commit if PRAGMA synchronous is set to FULL"
        }
      ]
    }
  ]
}
